export function resolveOfficialUnitInfo(currentUser, explicitUnitCode = null) {
  const rawKey = (
    explicitUnitCode ||
    currentUser?.kode_unit_kerja ||
    currentUser?.unit_kerja_id ||
    currentUser?.kode_unit ||
    'UN58.10'
  )
    .toString()
    .trim()
    .toUpperCase();

  if (OFFICIAL_UNIT_CODE_MAP[rawKey]) {
    return OFFICIAL_UNIT_CODE_MAP[rawKey];
  }

  if (rawKey.startsWith('UN58')) {
    const parentPrefix = rawKey.split('.').slice(0, 2).join('.');
    const parentMatch = OFFICIAL_UNIT_CODE_MAP[parentPrefix];
    return {
      kode: rawKey,
      short: parentMatch?.short || rawKey,
      nama: currentUser?.unit_name || parentMatch?.nama || `Unit Kerja ${rawKey}`
    };
  }

  return {
    kode: 'UN58.10',
    short: 'FKIP',
    nama: 'Fakultas Keguruan dan Ilmu Pendidikan (FKIP)'
  };
}

export function mapSecurityLabelToCode(securityLabel) {
  const norm = String(securityLabel || '').toUpperCase();
  if (norm === 'SR' || norm.includes('SANGAT RAHASIA')) return 'SR';
  if (norm === 'R' || (norm.includes('RAHASIA') && !norm.includes('SANGAT'))) return 'R';
  return 'B';
}

export function getJraItemByCode(kodeKlasifikasi, customList = []) {
  const code = String(kodeKlasifikasi || '').trim().toUpperCase();
  const foundInMaster = JRA_MASTER_ITEMS.find((item) => item.kode_klasifikasi === code);
  if (foundInMaster) return foundInMaster;

  const foundInCustom = (customList || []).find(
    (item) => (item.kode_klasifikasi || item.kode_jra) === code
  );
  if (foundInCustom) {
    const prefix = code.split('.')[0] || 'KP';
    const subPrefix = code.split('.').slice(0, 2).join('.') || `${prefix}.00`;
    const primaryObj = JRA_PRIMARY_CATEGORIES.find((c) => c.kode === prefix);
    const subObj = JRA_SUB_CATEGORIES.find((s) => s.kode_sub === subPrefix);
    const label = foundInCustom.keterangan_klasifikasi || foundInCustom.series_arsip || code;
    return {
      kode_klasifikasi: code,
      kode_utama: prefix,
      nama_utama: primaryObj?.nama || foundInCustom.nama_klasifikasi || prefix,
      kode_sub: subPrefix,
      nama_sub: subObj?.nama_sub || subPrefix,
      perihal: label,
      nama_klasifikasi: label,
      keterangan_klasifikasi: label,
      deskripsi_jra: label,
      retensi_aktif: foundInCustom.retensi_aktif_tahun || 2,
      retensi_inaktif: foundInCustom.retensi_inaktif_tahun || 3,
      nasib_akhir: foundInCustom.keterangan_akhir || 'Permanen',
      klasifikasi_keamanan: foundInCustom.klasifikasi_keamanan || 'Biasa/Terbuka',
      kode_keamanan: mapSecurityLabelToCode(foundInCustom.klasifikasi_keamanan),
      hak_akses: 'Sesuai SKKAAD SK Rektor No. 2803/2023',
      unit_pengolah: foundInCustom.unit_pengolah_default || 'Unit Kerja Terkait'
    };
  }

  return JRA_MASTER_ITEMS.find((i) => i.kode_klasifikasi === 'KP.04.03') || JRA_MASTER_ITEMS[0];
}

/**
 * Perakitan Nomor Surat Otomatis (Auto-Generated Number)
 * Sesuai Peraturan Rektor UNSIL No. 3 Tahun 2023 (Hal. 13-14 & Hal. 74-75) & SK Rektor No. 2803 Tahun 2023:
 * Rumus: Nomor Urut / Kode Unit Kerja / [Kode Keamanan] / Kode Klasifikasi / Tahun
 * Contoh 1 (dengan Kode Keamanan): 83/UN58.10/B/KP.04.03/2026 atau 18/UN58/R/PR.00.02/2026
 * Contoh 2 (tanpa Kode Keamanan / Naskah Unit Hal. 75): 83/UN58.10/KP.04.03/2026
 */
export function assembleOfficialLetterNumber(params = {}) {
  const rawSeq = params.nomorUrut !== undefined ? params.nomorUrut : params.seqNumber !== undefined ? params.seqNumber : 83;
  const rawUnit = params.kodeUnit || params.unitCode || 'UN58.10';
  const rawSec = params.kodeKeamanan !== undefined ? params.kodeKeamanan : params.securityCode !== undefined ? params.securityCode : 'B';
  const rawKlas = params.kodeKlasifikasi || params.klasifikasiCode || 'KP.04.03';
  const rawYear = params.tahun || params.year || new Date().getFullYear();
  const includeSec = params.includeSecuritySegment !== undefined ? params.includeSecuritySegment : Boolean(rawSec && String(rawSec).trim() !== '' && String(rawSec).toUpperCase() !== 'NONE');

  const cleanUnit = String(rawUnit).trim();
  const cleanKlas = String(rawKlas).trim();
  const cleanYear = String(rawYear).trim();
  const cleanSeq =
    typeof rawSeq === 'number'
      ? params.padThreeDigits
        ? String(Math.max(1, rawSeq)).padStart(3, '0')
        : String(Math.max(1, rawSeq))
      : String(rawSeq || '83').trim();

  if (!includeSec) {
    return `${cleanSeq}/${cleanUnit}/${cleanKlas}/${cleanYear}`;
  }

  const cleanSec = ['B', 'R', 'SR'].includes(String(rawSec).toUpperCase())
    ? String(rawSec).toUpperCase()
    : 'B';

  return `${cleanSeq}/${cleanUnit}/${cleanSec}/${cleanKlas}/${cleanYear}`;
}
